# is-transactional es opcional. 1 (por defecto): mensaje transaccional. 0: mensaje comercial (publicidad, promociones);
# los numeros inscritos en el Registro de Numeros Excluidos (RNE) que no aceptan SMS se rechazan con el error 1010.
curl -X POST "https://www.onurix.com/api/v1/sms/send" -d key="AQUI_SU_KEY" -d client="AQUI_SU_CLIENT" -d phone="AQUI_EL_NUMERO_DE_CELULAR" -d sms="AQUI_EL_SMS_A_ENVIAR" -d groups="AQUI_ID_DE_GRUPO" -d is-transactional="1" -H 'Content-Type: application/x-www-form-urlencoded' -H 'Accept: application/json'